// What the reviewer is asked: the person's own request (the caption is how it was put to the model)
return `The person asked for: ${request}

The caption the picture was made from: ${caption}

Check the picture against what the person asked for.`;

// The prompt for this try: the enhanced one, and on a retry the last review's fix with it (a model told what to
// get right this time; the review read as the step before it left it, the loop's last try)
const last = nodes.verdict;
const fix = attempt > 1 && last && typeof last.fix === 'string' ? last.fix.trim() : '';
return fix ? `${caption}\n\n${fix}` : caption;

data.systemPrompt:
You check a picture an image model made against what the person asked for. Reply with JSON alone, no prose and no code fence, in exactly this shape:
{"pass": true or false, "issues": ["each real problem, in a few words"], "fix": "one sentence saying what the picture must show instead, as an instruction to the painter, or empty", "text": {"requested": [each word or phrase the request asks to be written in the picture, exactly as asked: lettering, never the things it shows], "found": [each word or phrase you can read in the picture, letter by letter]}}
Pass when the picture shows what was asked: the subjects and how many, any text exactly as asked (read it letter by letter: a wrong, missing or extra letter is an issue), the colours, the setting and the style. Other text is an issue only where it gets in the way: garbled letters on or beside the text asked for, or any text at all on a picture meant to be clean (a logo, an icon, a product shot); the signs and labels a scene would have anyway, and a reflection's mirrored letters, are fine. Detail the request does not mention is not an issue. Fail only for a problem the person would notice. The text lists hold the words alone; leave them empty where there is no text.

data.code:
// Pass or try again: the review read from its reply (a reply that is not JSON cannot fail the picture: it is kept
// as text, the picture passed unchecked), with the picture's file reference. The lettering is checked here too: the
// reviewer lists what it reads, and each phrase that must be there has to be among it (a small vision model reading
// a picture is reliable; one judging whether it matches is lenient)
const text = String(review == null ? '' : review).trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
const at = text.indexOf('{'), end = text.lastIndexOf('}');
let found = null;
try { found = JSON.parse(at >= 0 && end > at ? text.slice(at, end + 1) : text); } catch { found = null; }
const checked = !!found && typeof found.pass === 'boolean';
const issues = checked && Array.isArray(found.issues) ? found.issues.filter((x) => typeof x === 'string' && x.trim()) : [];
const words = (s) => String(s).toUpperCase().replace(/[^A-Z0-9\u00C0-\uFFFF]+/g, ' ').trim();
const lists = checked && found.text && typeof found.text === 'object' ? found.text : {};
const strings = (v) => (Array.isArray(v) ? v.filter((x) => typeof x === 'string' && words(x)) : []);
const read = ` ${strings(lists.found).map(words).join(' ')} `;
// (each phrase the caption quotes: the enhancer quotes exactly the lettering the picture must show, the request's own
// and, for an edit, what the references show that the request leaves alone)
const must = [];
String(caption == null ? '' : caption).replace(/["\u201C]([^"\u201D]{1,60})["\u201D]/g, (all, q) => { must.push(q); return all; });
const missing = checked ? [...new Set(must.map(words).filter(Boolean))].filter((p) => !read.includes(` ${p} `)) : [];
for (const p of missing) issues.push(`the text "${p}" is not in the picture`);
const fix = [checked && typeof found.fix === 'string' ? found.fix.trim() : '', ...missing.map((p) => `The text "${p}" must be written in it, exactly.`)].filter(Boolean).join(' ');
return {
  pass: checked ? found.pass === true && missing.length === 0 : true,
  checked,
  attempt,
  image: (made && made.file) || image,
  seed: made && made.seed != null ? made.seed : null,
  issues,
  fix,
  text: checked ? { requested: strings(lists.requested), quoted: must, found: strings(lists.found), missing } : null,
  review: checked ? null : text,
};

// The flow's answer: the picture (its file's URL, never the picture itself), whether it passed, and each try's
// findings. The first try that passed, else the try with the fewest issues (the latest of those).
const tries = Array.isArray(attempts) ? attempts.filter((t) => t && typeof t === 'object') : [];
let best = tries.find((t) => t.pass) || null;
if (!best) for (const t of tries) if (!best || t.issues.length <= best.issues.length) best = t;
return {
  image: best ? best.image : null,
  pass: !!(best && best.pass),
  checked: !!(best && best.checked),
  tries: tries.length,
  issues: best ? best.issues : [],
  text: best ? best.text : null,
  prompt,
  caption,
  attempts: tries.map((t) => ({ image: t.image, pass: t.pass, issues: t.issues, seed: t.seed })),
};
